    pub app_version: Option<String>,
    /// Aircraft drone model code (e.g. 67).
    pub drone_type: Option<u8>,
    /// Aircraft marketing model name (e.g. "Mavic 3 Pro").
    pub aircraft_model: Option<String>,
    /// User-assigned aircraft nickname.
    pub aircraft_name: Option<String>,
    /// Hardware airframe serial number.
    pub aircraft_serial: Option<String>,
    /// Camera gimbal payload serial number.
    pub camera_serial: Option<String>,
    /// Remote controller hardware serial number.
    pub rc_serial: Option<String>,
    /// Primary battery serial number.
    pub battery_serial: Option<String>,
    /// ISO 8601 UTC session start timestamp.
    pub start_time_utc: Option<String>,
    /// UTC Unix timestamp in milliseconds when logging commenced.
    pub start_time_utc_ms: i64,
    /// ISO 8601 UTC session termination timestamp.
    pub end_time_utc: Option<String>,
    /// Total recording duration in seconds (from first to last sample).
    pub duration_seconds: f64,
    /// Total airborne duration in seconds (motors armed and running).
    pub flight_duration_seconds: f64,
    /// Cumulative 3D flight distance traveled in meters.
    pub total_distance_meters: f64,
    /// Maximum altitude Above Ground Level in meters.
    pub max_altitude_agl_m: f64,
    /// Maximum altitude above Mean Sea Level in meters.
    pub max_altitude_msl_m: f64,
    /// Takeoff surface elevation above Mean Sea Level in meters.
    pub takeoff_elevation_msl_m: f64,
    /// Maximum horizontal ground speed achieved in m/s.
    pub max_horizontal_speed_mps: f64,
    /// Maximum vertical ascent or descent rate achieved in m/s.
    pub max_vertical_speed_mps: f64,
    /// Calibrated Home Point latitude in decimal degrees.
    pub home_latitude: Option<f64>,
    /// Calibrated Home Point longitude in decimal degrees.
    pub home_longitude: Option<f64>,
    /// Calibrated Home Point elevation MSL in meters.
    pub home_altitude_msl: Option<f64>,
    /// Configured Return-To-Home cruise altitude in meters.
